-- Hyprland Lua config (converted from hyprland.conf).
-- Docs: https://wiki.hypr.land/Configuring/Start/
--
-- NOTE: hyprland.conf is kept as-is. If hyprland.lua exists it is loaded
-- INSTEAD of hyprland.conf, so to fall back just rename/remove this file.

-- Colors are generated by matugen -> ~/.config/hypr/colors.lua
local colors = require("colors")


------------------
---- MONITORS ----
------------------

-- Original had two monitor lines; the later one set scale = 1, which wins.
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "1",
})


---------------------
---- MY PROGRAMS ----
---------------------

local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "qs ipc call launcherWindow toggle"
local mainMod     = "SUPER"


-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    hl.exec_cmd("nm-applet")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("kdeconnectd")
    hl.exec_cmd("kdeconnect-indicator")
    hl.exec_cmd("wl-paste --watch cliphist store")
    hl.exec_cmd("qs")
end)


