hl.bind("ALT + SHIFT + N", hl.dsp.exec_cmd("qs ipc call networkPanel changeVisible"))
hl.bind("ALT + SHIFT + C", hl.dsp.exec_cmd("qs ipc call controlCenter changeVisible"))
