---- WINDOWS AND WORKSPACES ----
--------------------------------

hl.window_rule({
    name           = "suppress-maximize-events",
    match          = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    name      = "slack-ws2",
    match     = { class = "^(Slack)$" },
    workspace = "2",
    opacity   = "1 1",
})

hl.window_rule({
    name      = "spotify-ws3",
    match     = { class = "^(spotify)$" },
    workspace = "3",
    opacity   = "0.75 0.75",
})

hl.window_rule({
    name      = "discord-ws4",
    match     = { class = "^(discord)$" },
    workspace = "4",
    opacity   = "1 1",
})

hl.window_rule({
    name    = "chrome-opacity",
    match   = { class = "^(Google-chrome)$" },
    opacity = "0.85 0.85",
})

hl.window_rule({
    name    = "blueman-opacity",
    match   = { class = "^(blueman-manager)$" },
    opacity = "0.9 0.9",
})
